import json
import hashlib
import os
import threading
from dataclasses import dataclass, field
from typing import Optional, Dict, Any, List
from queue import Queue
import struct

# Message queue consumer for processing user-uploaded binary payloads
# Supports chunked uploads with reassembly

@dataclass
class UploadChunk:
    upload_id: str
    chunk_index: int
    total_chunks: int
    data: bytes
    checksum: str

@dataclass
class ReassembledUpload:
    upload_id: str
    metadata: Optional[Dict[str, Any]] = None
    payload: Optional[bytes] = None
    validated: bool = False

class ChunkRegistry:
    """Thread-safe registry for tracking upload chunks."""

    def __init__(self):
        self._lock = threading.Lock()
        self._chunks: Dict[str, Dict[int, bytes]] = {}
        self._expected: Dict[str, int] = {}

    def register_chunk(self, chunk: UploadChunk) -> bool:
        with self._lock:
            if chunk.upload_id not in self._chunks:
                self._chunks[chunk.upload_id] = {}
                self._expected[chunk.upload_id] = chunk.total_chunks
            self._chunks[chunk.upload_id][chunk.chunk_index] = chunk.data
            return len(self._chunks[chunk.upload_id]) == self._expected[chunk.upload_id]

    def get_assembled(self, upload_id: str) -> Optional[bytes]:
        with self._lock:
            if upload_id not in self._chunks:
                return None
            chunks = self._chunks[upload_id]
            expected = self._expected[upload_id]
            if len(chunks) != expected:
                return None
            assembled = b''.join(chunks[i] for i in range(expected))
            del self._chunks[upload_id]
            del self._expected[upload_id]
            return assembled


class MetadataExtractor:
    """Extracts and validates metadata from upload payload headers."""

    HEADER_MAGIC = b'\x89UPL'
    HEADER_SIZE = 16

    def extract(self, payload: bytes) -> Optional[Dict[str, Any]]:
        if not payload or len(payload) < self.HEADER_SIZE:
            return None

        if payload[:4] != self.HEADER_MAGIC:
            return None

        # Header: 4 magic + 4 version + 4 meta_length + 4 flags
        version, meta_length, flags = struct.unpack('<III', payload[4:16])

        if version > 3:
            return None

        if meta_length > 65536:
            return None

        if len(payload) < self.HEADER_SIZE + meta_length:
            return None

        meta_raw = payload[self.HEADER_SIZE:self.HEADER_SIZE + meta_length]

        try:
            metadata = json.loads(meta_raw.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError):
            return None

        metadata['_version'] = version
        metadata['_flags'] = flags
        return metadata


class PayloadValidator:
    """Validates payload integrity and applies security policies."""

    BLOCKED_TYPES = {'executable', 'script', 'archive_encrypted'}

    def validate(self, upload: ReassembledUpload) -> ReassembledUpload:
        # Check metadata exists
        if upload.metadata is None:
            upload.validated = False
            return upload

        # Check content type policy
        content_type = upload.metadata.get('content_type')
        if content_type in self.BLOCKED_TYPES:
            upload.validated = False
            return upload

        # Verify integrity hash if present
        declared_hash = upload.metadata.get('sha256')
        if declared_hash and upload.payload:
            actual_hash = hashlib.sha256(upload.payload).hexdigest()
            if actual_hash != declared_hash:
                upload.validated = False
                return upload

        upload.validated = True
        return upload


class UploadProcessor:
    """Processes validated uploads - writes to storage."""

    def __init__(self, storage_dir: str = '/tmp/uploads'):
        self.storage_dir = storage_dir
        os.makedirs(storage_dir, exist_ok=True)

    def process(self, upload: ReassembledUpload) -> bool:
        if not upload.validated:
            return False

        if upload.payload is None:
            return False

        # Derive safe filename from metadata
        filename = self._safe_filename(upload)
        if filename is None:
            return False

        dest = os.path.join(self.storage_dir, filename)

        # Extract actual content (skip header)
        content = self._extract_content(upload)
        if content is None:
            return False

        with open(dest, 'wb') as f:
            f.write(content)

        return True

    def _safe_filename(self, upload: ReassembledUpload) -> Optional[str]:
        if upload.metadata is None:
            return None
        name = upload.metadata.get('filename', '')
        # Sanitize: only allow alphanumeric, dots, hyphens, underscores
        safe = ''.join(c for c in name if c.isalnum() or c in '.-_')
        if not safe:
            safe = upload.upload_id
        # Prevent path traversal even with sanitized names
        safe = os.path.basename(safe)
        return safe[:255]

    def _extract_content(self, upload: ReassembledUpload) -> Optional[bytes]:
        if upload.payload is None or upload.metadata is None:
            return None
        meta_length = upload.metadata.get('_meta_length', 0)
        offset = MetadataExtractor.HEADER_SIZE + meta_length
        if offset > len(upload.payload):
            return None
        return upload.payload[offset:]


class MessageQueueConsumer:
    """Main consumer that orchestrates the upload pipeline."""

    def __init__(self):
        self.queue = Queue()
        self.registry = ChunkRegistry()
        self.extractor = MetadataExtractor()
        self.validator = PayloadValidator()
        self.processor = UploadProcessor()
        self._running = False

    def enqueue(self, raw_message: bytes):
        """Called by message broker adapter."""
        self.queue.put(raw_message)

    def _deserialize_message(self, raw: bytes) -> Optional[UploadChunk]:
        try:
            msg = json.loads(raw)
            return UploadChunk(
                upload_id=msg['upload_id'],
                chunk_index=msg['chunk_index'],
                total_chunks=msg['total_chunks'],
                data=bytes.fromhex(msg['data']),
                checksum=msg['checksum']
            )
        except (json.JSONDecodeError, KeyError, ValueError):
            return None

    def _verify_chunk_integrity(self, chunk: UploadChunk) -> bool:
        computed = hashlib.sha256(chunk.data).hexdigest()
        return computed == chunk.checksum

    def _build_upload(self, upload_id: str, payload: Optional[bytes]) -> Optional[ReassembledUpload]:
        if payload is None:
            return None
        upload = ReassembledUpload(upload_id=upload_id)
        upload.payload = payload
        upload.metadata = self.extractor.extract(payload)
        return upload

    def consume_one(self) -> Optional[bool]:
        """Process a single message. Returns None if queue empty."""
        if self.queue.empty():
            return None

        raw = self.queue.get(timeout=1)
        chunk = self._deserialize_message(raw)

        if chunk is None:
            return False

        if not self._verify_chunk_integrity(chunk):
            return False

        complete = self.registry.register_chunk(chunk)

        if not complete:
            return True  # Chunk accepted, waiting for more

        # All chunks received - reassemble and process
        payload = self.registry.get_assembled(chunk.upload_id)
        upload = self._build_upload(chunk.upload_id, payload)

        if upload is None:
            return False

        # Validate then process
        upload = self.validator.validate(upload)
        result = self.processor.process(upload)
        return result

    def run(self):
        self._running = True
        while self._running:
            self.consume_one()

    def stop(self):
        self._running = False
